import { useState } from 'react';
import { nearest, type Row } from '../lib/chart';
import { Tooltip } from './Tooltip';

type Props = { rows: Row[] };

export function UsageChart({ rows }: Props) {
  const [hover, setHover] = useState<Row | null>(null)
  const onMove = (e: MouseEvent) => { /* find nearest row */ setHover(nearest(rows, e.clientX)) }
  return <svg onMouseMove={onMove}>{/* bars */}{hover && <Tooltip row={hover} />}</svg>
}

